                if d < bestd or (d == bestd and (x, y) < (tx, ty)):
                    bestd, tx, ty = d, x, y
        elif opp_set:
            bestd = 10**9
            for x, y in opp_set:
                d = abs(x - sx) + abs(y - sy)
                if d < bestd or (d == bestd and (x, y) < (tx, ty)):
                    bestd, tx, ty = d, x, y
        else:
            tx, ty = (ox, oy)

